function hash(str){ var h=2166136261; for(var i=0;i<str.length;i++){ h^=str.charCodeAt(i); h=Math.imul(h,16777619); } return h>>>0; }
function pick(rng, arr){ return arr[Math.floor(rng()*arr.length)]; }
function acrostic(keyword, opts){ opts=opts||{}; keyword=String(keyword||'').trim(); if(!keyword) return {error:'请输入关键字'};
  var seed=opts.seed!=null?opts.seed:hash(keyword); var rng=rngFactory(seed);
  var lines=[]; for(var i=0;i<keyword.length;i++){ var ch=keyword[i]; lines.push(ch+'：'+pick(rng,POOL)); }
  return {keyword:keyword, lines:lines, seed:seed}; }
var EXPORTS={acrostic:acrostic, hash:hash};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
